/* Global & Reset */
[hidden] {
  display: none !important;
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --bg-color: #1a1423;
  --card-bg: #2d1e2f;
  --accent-gold: #f6c445;
  --accent-gold-dark: #b8860b;
  --text-main: #f7f4ea;
  --text-muted: #bda0bc;
  --btn-bg: #37718e;
  --btn-hover: #488ea8;
  --btn-active: #2b566c;
  --btn-disabled: #4a4453;
  --border-color: #4b384f;
}

body {
  min-height: 100vh;
  background-color: var(--bg-color);
  color: var(--text-main);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  font-size: 16px;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 1rem;
}

.game-container {
  width: 100%;
  max-width: 420px;
  min-width: 320px;
  background-color: var(--card-bg);
  border: 4px solid var(--border-color);
  border-radius: 8px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.45);
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

.game-header {
  text-align: center;
}

.game-header h1 {
  font-size: 1.6rem;
  color: var(--accent-gold);
  letter-spacing: 0.05em;
  margin-bottom: 0.25rem;
}

.subtitle {
  font-size: 0.875rem;
  color: var(--text-muted);
}

.scene-card {
  display: flex;
  justify-content: center;
  align-items: center;
  background-color: #150e18;
  border: 2px solid var(--border-color);
  border-radius: 4px;
  padding: 0.5rem;
}

#mine-canvas {
  display: block;
  image-rendering: pixelated;
  background-color: #110d14;
  width: 100%;
  max-width: 280px;
  height: auto;
}

.stats-card {
  display: flex;
  justify-content: space-around;
  align-items: center;
  background-color: #211523;
  border: 2px solid var(--border-color);
  border-radius: 6px;
  padding: 0.85rem 0.5rem;
}

.stat-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.25rem;
}

.stat-label {
  font-size: 0.85rem;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.stat-value {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--accent-gold);
}

.stat-divider {
  width: 2px;
  height: 36px;
  background-color: var(--border-color);
}

.shop-card {
  display: flex;
  justify-content: space-between;
  align-items: center;
  background-color: #211523;
  border: 2px solid var(--border-color);
  border-radius: 6px;
  padding: 1rem;
  gap: 1rem;
}

.item-info {
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
}

.item-title {
  font-weight: 700;
  font-size: 1rem;
  color: var(--text-main);
}

.item-desc {
  font-size: 0.825rem;
  color: var(--text-muted);
}

.item-owned {
  font-size: 0.85rem;
  color: var(--accent-gold);
  margin-top: 0.25rem;
}

.pixel-btn {
  cursor: pointer;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 0.6rem 1rem;
  background-color: var(--btn-bg);
  color: #ffffff;
  border: 2px solid #579dbd;
  border-radius: 4px;
  font-size: 0.95rem;
  font-weight: 600;
  text-shadow: 1px 1px 0px rgba(0, 0, 0, 0.6);
  box-shadow: 0 4px 0 #1b3a49;
  transition: background-color 0.15s, transform 0.05s, box-shadow 0.05s;
  white-space: nowrap;
  min-width: 110px;
}

.pixel-btn:hover:not(:disabled) {
  background-color: var(--btn-hover);
}

.pixel-btn:focus-visible {
  outline: 3px solid var(--accent-gold);
  outline-offset: 2px;
}

.pixel-btn:active:not(:disabled) {
  transform: translateY(3px);
  box-shadow: 0 1px 0 #1b3a49;
  background-color: var(--btn-active);
}

.pixel-btn:disabled {
  background-color: var(--btn-disabled);
  border-color: #5d5667;
  box-shadow: 0 4px 0 #2a2531;
  color: #8c8297;
  cursor: not-allowed;
  text-shadow: none;
}

.btn-cost {
  font-size: 0.75rem;
  font-weight: 400;
  opacity: 0.9;
}

@media (max-width: 380px) {
  .shop-card {
    flex-direction: column;
    align-items: stretch;
    text-align: center;
  }

  .pixel-btn {
    width: 100%;
  }
}

document.addEventListener('DOMContentLoaded', () => {
  const DRILL_COST = 10;
  const BASE_RATE = 1;
  const DRILL_BONUS = 1;

  const state = {
    gold: 0,
    drills: 0,
    ratePerSecond: BASE_RATE
  };

  const goldDisplay = document.getElementById('gold-display');
  const rateDisplay = document.getElementById('rate-display');
  const drillCount = document.getElementById('drill-count');
  const buyDrillBtn = document.getElementById('buy-drill-btn');
  const canvas = document.getElementById('mine-canvas');
  const ctx = canvas ? canvas.getContext('2d') : null;

  function updateUI() {
    goldDisplay.textContent = state.gold;
    rateDisplay.textContent = `${state.ratePerSecond}/s`;
    drillCount.textContent = state.drills;

    const canAfford = state.gold >= DRILL_COST;
    buyDrillBtn.disabled = !canAfford;
  }

  function handleBuyDrill() {
    if (state.gold >= DRILL_COST) {
      state.gold -= DRILL_COST;
      state.drills += 1;
      state.ratePerSecond = BASE_RATE + (state.drills * DRILL_BONUS);
      updateUI();
    }
  }

  buyDrillBtn.addEventListener('click', handleBuyDrill);

  // Primary 1-second gold production loop
  setInterval(() => {
    state.gold += state.ratePerSecond;
    updateUI();
  }, 1000);

  // Pixel art canvas rendering
  let frame = 0;
  function drawPixelMine() {
    if (!ctx) return;
    frame++;

    ctx.fillStyle = '#18121d';
    ctx.fillRect(0, 0, 280, 140);

    // Cave walls and floor
    ctx.fillStyle = '#3a273b';
    for (let x = 0; x < 280; x += 14) {
      ctx.fillRect(x, 126, 14, 14);
      ctx.fillRect(x, 0, 14, 14);
    }

    // Golden ore veins
    ctx.fillStyle = '#f6c445';
    const oreOffsets = [40, 90, 160, 220];
    oreOffsets.forEach((ox) => {
      ctx.fillRect(ox, 120, 6, 6);
      ctx.fillRect(ox + 4, 116, 4, 4);
    });

    // Miner pickaxe animation
    const swing = Math.sin(frame * 0.1) * 6;
    ctx.fillStyle = '#bda0bc'; // Miner body
    ctx.fillRect(50, 85, 16, 35);
    ctx.fillStyle = '#f7f4ea'; // Head
    ctx.fillRect(52, 70, 12, 12);
    ctx.fillStyle = '#f6c445'; // Hardhat
    ctx.fillRect(50, 66, 16, 6);
    ctx.fillStyle = '#9b829c'; // Pickaxe handle
    ctx.fillRect(66 + swing, 75 + swing, 4, 20);
    ctx.fillStyle = '#e0e0e0'; // Pickaxe head
    ctx.fillRect(62 + swing, 72 + swing, 12, 4);

    // Drills rendering
    const activeDrills = Math.min(state.drills, 3);
    for (let i = 0; i < activeDrills; i++) {
      const dx = 120 + (i * 45);
      const jitter = (frame % 4 < 2) ? 1 : 0;

      ctx.fillStyle = '#37718e'; // Drill mount
      ctx.fillRect(dx, 85, 18, 30);
      ctx.fillStyle = '#a6b9c7'; // Drill bit
      ctx.fillRect(dx + 6, 115 + jitter, 6, 10);
      ctx.fillStyle = '#f6c445'; // Sparks
      if (frame % 6 < 3) {
        ctx.fillRect(dx + 2, 122, 2, 2);
        ctx.fillRect(dx + 12, 121, 2, 2);
      }
    }

    requestAnimationFrame(drawPixelMine);
  }

  updateUI();
  drawPixelMine();
});
